import string

INPUT_FILE = '/home/ctfplayer/ctf_files/terminal_velocity_screen.txt'
MIN_LEN = 8
HEADER_ROWS = 5  # guess: skip first 5 rows, adjust with actual banner seen
PRINTABLE = set(string.printable) - set('\r\x0b\x0c')  # skip control chars except \n

def is_printable(c):
    return c in PRINTABLE and c != '\n'

def extract_candidates(lines, min_len):
    result = []
    for row, line in enumerate(lines):
        col = 0
        buf = ''
        buf_start = None
        while col < len(line):
            c = line[col]
            if is_printable(c):
                if not buf:
                    buf_start = col
                buf += c
            else:
                if len(buf) >= min_len:
                    result.append((row, buf_start, buf))
                buf = ''
                buf_start = None
            col += 1
        if len(buf) >= min_len:
            result.append((row, buf_start, buf))
    return result

def visually_report(lines):
    for row, line in enumerate(lines):
        if any(x in line for x in ("flag", "password", "pw", "pass")):
            print(f"Visually flaggable on row {row}: {line.strip()}")

with open(INPUT_FILE, 'r', errors='replace') as f:
    lines = f.readlines()

# Exclude header/banner
lines_ = lines[HEADER_ROWS:]

candidates = extract_candidates([l.rstrip('\n') for l in lines_], MIN_LEN)
print("Candidate strings of 8+ chars with (row,col):")
for row, col, s in candidates:
    print(f"({row+HEADER_ROWS},{col}): {repr(s)}")

print("\n--- Visual password/hash search ---")
visually_report(lines_)

import string

FILENAME = '/home/ctfplayer/ctf_files/terminal_velocity_screen.txt'
MINLEN = 8

# Helper to check printable (non-space) chars
is_printable = lambda c: c in string.printable and c != ' '

with open(FILENAME) as f:
    lines = [l.rstrip('\n') for l in f]

# Pad all lines to equal length (80 columns)
cols = 80
for i in range(len(lines)):
    lines[i] = lines[i].ljust(cols)
rows = len(lines)

results = []

# 1. Check columns (vertical)
for col in range(cols):
    run = ''
    start_row = None
    for row in range(rows):
        c = lines[row][col]
        if is_printable(c):
            if run == '':
                start_row = row
            run += c
        else:
            if len(run) >= MINLEN:
                results.append({'pos': (start_row, col), 'dir': 'vertical', 'content': run})
            run = ''
            start_row = None
    if len(run) >= MINLEN:
        results.append({'pos': (start_row, col), 'dir': 'vertical', 'content': run})

# 2a. Main diagonals (\)
for d in range(-(rows-1), cols):   # diagonals: i-j = d
    run = ''
    start = None
    for row in range(rows):
        col = row + d
        if 0 <= col < cols:
            c = lines[row][col]
            if is_printable(c):
                if run == '':
                    start = (row, col)
                run += c
            else:
                if len(run) >= MINLEN:
                    results.append({'pos': start, 'dir': 'main-diag', 'content': run})
                run = ''
                start = None
    if len(run) >= MINLEN:
        results.append({'pos': start, 'dir': 'main-diag', 'content': run})

# 2b. Anti-diagonals (/)
for d in range(0, rows + cols - 1):  # i+j = d
    run = ''
    start = None
    for row in range(rows):
        col = d - row
        if 0 <= col < cols:
            c = lines[row][col]
            if is_printable(c):
                if run == '':
                    start = (row, col)
                run += c
            else:
                if len(run) >= MINLEN:
                    results.append({'pos': start, 'dir': 'anti-diag', 'content': run})
                run = ''
                start = None
    if len(run) >= MINLEN:
        results.append({'pos': start, 'dir': 'anti-diag', 'content': run})

# Print results and flag candidates
flag_like = []
for r in results:
    if 'flag{' in r['content']:
        print(f"FLAG FOUND: {r['content']} at {r['pos']} {r['dir']}")
    if 'flag' in r['content'] or 'password' in r['content'].lower() or len(r['content']) >= 16:
        flag_like.append(r)

if flag_like:
    print('\nFlag/password/long candidate runs:')
    for r in flag_like:
        print(f"{r['pos']} {r['dir']}: {r['content']}")
else:
    print("\nNo password/flag runs found. All runs:")
    for r in results:
        print(f"{r['pos']} {r['dir']}: {r['content']}")

# Final fallback: printable character dump (no spaces)
print('\nFlat dump (all non-space printable chars, row-wise):')
flat = ''.join(c for l in lines for c in l if is_printable(c))
print(flat)

