import sys

data = open(sys.argv[1], 'rb').read().decode('utf-8', errors='replace')
# Find all cursor movement commands of the form \x1b[{row};{col}H,
# and the visible character at that point in data

positions = []
cursor_re = re.compile(r'\x1b\[([0-9]+);([0-9]+)H')
last = 0
for m in cursor_re.finditer(data):
    row, col = int(m.group(1)), int(m.group(2))
    positions.append((m.start(), row, col))

# Create a grid of [row][col] initialized with ' '
grid = {}
for idx in range(len(positions)):
    pos, row, col = positions[idx]
    char = None
    if idx+1 < len(positions):
        frag = data[pos+len(positions[idx][0]):positions[idx+1][0]]
        # usually one printable char
    else:
        frag = data[pos+len(cursor_re.pattern):]
    # extract the first printable
    for c in frag:
        if 32 <= ord(c) < 127:
            char = c
            break
    if char:
        if row not in grid:
            grid[row] = {}
        grid[row][col] = char

# Print a rectangular region covering min/max row/col
minr, maxr = min(grid), max(grid)
minc, maxc = 1000, 0
for r in grid:
    for c in grid[r]:
        minc = min(minc, c)
        maxc = max(maxc, c)

for r in range(minr, maxr+1):
    line = ''
    for c in range(minc, maxc+1):
        line += grid.get(r, {}).get(c, ' ')
