import telnetlib
import time
import pyte
import re

HOST = 'misc.chal.csaw.io'
PORT = 3535

def get_screen_rows(screen):
    # pyte's screen has .lines (OrderedDict), key is row number
    rows = []
    for y in sorted(screen.buffer.keys()):
        row = ''.join([screen.buffer[y][x].data if x in screen.buffer[y] else ' ' for x in range(screen.columns)])
        rows.append(row)
    return rows

def plausible_candidates(rows):
    candidates = set()
    flaglike = re.compile(r'[A-Za-z0-9_{}]{6,}')
    for row in rows:
        for s in flaglike.findall(row):
            # Ignore rows that are only spaces
            if s.strip():
                candidates.add((s, row))
    return list(candidates)

def main():
    tn = telnetlib.Telnet(HOST, PORT)
    screen = pyte.Screen(80, 24)
    stream = pyte.Stream(screen)
    # Give it a moment to populate
    time.sleep(1)
    data = tn.read_very_eager()
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        text = data.decode('latin1', 'replace')
    stream.feed(text)
    rows = get_screen_rows(screen)
    print("Rows:")
    for row in rows:
        print(repr(row))
    print()
    candidates = plausible_candidates(rows)
    if len(candidates) == 0:
        print("No plausible candidates found.")
    else:
        print("Candidate strings:")
        for s, r in candidates:
            print(f"Candidate: {s}\nRow: {repr(r)}")

if __name__ == '__main__':
    main()

